NOTES = {
    "LA-SEN:letlow": "Transfers include $4.18M from her U.S. House campaign",
}


def finance(row):
    (cid, _, fec_id, start, end, total, small, large, pac, party, cand, cand_loans,
     transfers, other_loans, offsets, other_receipts, spent, cash, debts) = row
    parts = {"small": small, "large": large, "pac": pac, "party": party, "self": cand + cand_loans,
             "public": 0, "transfers": transfers, "other": other_loans + offsets + other_receipts}
    # Each line is rounded to the dollar on its own, so the parts can miss the total
    # by a few dollars; they are never padded to match (a $1 "other" line would be false).
    assert abs(total - sum(parts.values())) <= 5, (cid, total - sum(parts.values()))
    f = {"total": total, "parts": parts, "spent": spent, "cashOnHand": cash, "from": start, "asOf": end,
         "source": "FEC", "fecId": fec_id,
         "url": f"https://www.fec.gov/data/candidate/{fec_id}/?cycle=2026&election_full=true"}
    if debts:
        f["debts"] = debts
    if cid in NOTES:
        f["note"] = NOTES[cid]
    return f


races = {}
for row in SENATE + HOUSE:
    races.setdefault(row[0].split(":")[0], []).append({"id": row[0], "name": row[1], "finance": finance(row)})

# financeOnly: these races gain money, not researched positions (update_races.py
# leaves their "research" flag alone, so matching stays off where positions are missing).
write("data/research/fec.json", [{"id": rid, "financeOnly": True, "candidates": cands} for rid, cands in races.items()],
      "Receipts by source from candidates’ FEC financial summaries, read Oct. 25, 2026.", updated=READ)
